import { Step } from './step';
import { ReadOnlyStream } from './read-only-stream';
import { StepperNavigationChangeEvent } from './stepper-navigation-change-event';
export interface StepperNavigation {
    /** Getters */
    getActiveStep(): Step | undefined;
    getStepState(stepId: string): 'complete' | 'in-progress' | 'error' | undefined;
    getNonCompleteSteps(stepIds?: Array<string>): Array<string>;
    getStepIndexById(stepId: string): number | undefined;
    getSteps(): Array<Step>;
    getChangeStream(): ReadOnlyStream<StepperNavigationChangeEvent>;
    getIsStepDisabled(stepId: string): boolean;
    getIsSequential(): boolean;
    getIsFirstStepActive(): boolean;
    getIsLastStepActive(): boolean;
    getId(): string;
    /** Setters */
    setSteps(steps: Array<Step>): void;
    setStepToActive(step: number | string): void;
    setStepToComplete(step: number | string): void;
    setStepToInProgress(step: number | string): void;
    setStepToError(step: number | string): void;
    setStepToDefault(step: number | string): void;
    setStepState(step: number | string, state?: 'complete' | 'in-progress' | 'error'): any;
    setStepToDisabled(step: number | string): void;
    setIsSequential(isSequential: boolean): void;
    /** Navigation Functions */
    nextStep(): void;
    previousStep(): void;
}
